            body: JSON.stringify({
              model,
              messages: [ { role: 'system', content: SYSTEM_PROMPT }, { role: 'user', content: prompt } ],
              temperature: 0.1,
              response_format: { type: 'json_object' },
              stream: true,
              streamOptions: { includeUsage: true }
            })
          });
          if (!res.ok || !res.body) {
            const txt = await res.text().catch(() => '');
            logEvent('warning', 'fallback_stream_fail', { model, status: res.status, errorText: txt });
            throw new Error(`Falha streaming ${model}: ${res.status} ${txt}`);
          }
          const reader = res.body.getReader();
          const decoder = new TextDecoder();
          let buf = '';
          let eventCount = 0;
          let hasReasoningEvents = false;
          while (true) {
            const { value, done } = await reader.read();
            if (done) break;
            buf += decoder.decode(value, {
              stream: true
            });
            const parts = buf.split('\n\n');
            // Processar todos os blocos completos
            while (parts.length > 1) {
              const block = parts.shift(); // remove primeiro bloco
              const lines = block.split('\n');
              let eventName = 'message';
              let dataLine = '';
              for (const line of lines) {
                if (line.startsWith('event:')) eventName = line.slice(6).trim();
                if (line.startsWith('data:')) dataLine = line.slice(5).trim();
              }
              eventCount++;

              if (dataLine === '[DONE]') {
                continue;
              }
              if (dataLine) {
                try {
                  const json = JSON.parse(dataLine);
                  const choice = json?.choices?.[0] || {};
                  const delta = choice?.delta || {};
                  const message = choice?.message || {};
                  const usage = json?.usage || {};
                  const reasoning = delta?.reasoning || delta?.reasoning_content || message?.reasoning || json?.reasoning || null;
                  const reasoningDetails = delta?.reasoning_details || message?.reasoning_details || json?.reasoning_details || null;
                  if (!modelAnnounced && (reasoning || reasoningDetails || typeof delta?.content === 'string' || typeof message?.content === 'string')) {
                    modelAnnounced = true;
                    sendEvent('status', { message: 'Modelo selecionado', model, final: true });
                  }
                  if (reasoning) { hasReasoningEvents = true; }
                  if (reasoningDetails) { hasReasoningEvents = true; }
                  if (reasoning && !isGrokModel(model)) {
                    let chunkText = typeof reasoning === 'string' ? reasoning : JSON.stringify(reasoning);
                    chunkText = chunkText.replace(/\*+/g, '');
                    reasoningBuffer = appendOverlapDedup(reasoningBuffer, chunkText);
                    const normalized = normalizeReasoningText(reasoningBuffer);
                    const diff = normalized.slice(normalizedReasoningSent.length);
                    if (diff) {
                      sendEvent('reasoning', {
                        text: diff
                      });
                      normalizedReasoningSent = normalized;
                    }
                  }
                  if (reasoningDetails && !isGrokModel(model)) {
                    sendEvent('reasoning_details', {
                      details: reasoningDetails
                    });
                  }
                  if (typeof delta?.content === 'string') {
                    contentBuffer += delta.content;
                    sendEvent('delta', {
                      content: delta.content
                    });
                    if (delta.content.trim()) seenTextDelta = true;
                  }
                  if (!seenTextDelta && typeof message?.content === 'string' && message.content.trim()) {
                    contentBuffer += message.content;
                    sendEvent('delta', {
                      content: message.content
                    });
                  }
                  if (usage) {
                    const completionDetails = usage.completion_tokens_details || usage.completionTokensDetails || {};
                    const usagePrompt = usage.prompt_tokens ?? usage.promptTokens ?? 0;
                    const usageCompletion = usage.completion_tokens ?? usage.completionTokens ?? usage.output_tokens ?? 0;
                    // Capture latest non-zero usage for metrics recording
                    if (usagePrompt > 0) streamPromptTokens = usagePrompt;
                    if (usageCompletion > 0) streamCompletionTokens = usageCompletion;
                    sendEvent('usage', {
                      reasoningTokens: usage.reasoningTokens ?? usage.reasoning_tokens ?? completionDetails.reasoning_tokens ?? null,
                      totalTokens: usage.total_tokens ?? usage.totalTokens ?? null,
                      completionTokens: usageCompletion || null,
                      promptTokens: usagePrompt || null
                    });
                  }
                } catch (_) {
                  console.debug('[SSE] non-JSON chunk');
                }
              }
            }
            // Mantém o resto no buffer
            buf = parts[0] || '';
          }
          // Ao finalizar, enviar resultado
          let parsedResponse = null;
          try {
            let cleanResponse = contentBuffer.trim();
            if (cleanResponse.startsWith('```json')) {
              cleanResponse = cleanResponse.replace(/^```json\s*/, '').replace(/\s*```$/, '');
            }
            parsedResponse = JSON.parse(cleanResponse);
          } catch {
            sendEvent('error', {
              message: 'Erro ao processar resposta da IA'
            });
            throw new Error('Erro ao processar resposta da IA');
          }
          try {
            const categories = Array.isArray(parsedResponse?.categories) ? parsedResponse.categories : [];
            if (categories.length > 0) {
              const flattened = categories.flatMap((cat) => Array.isArray(cat?.items) ? cat.items.map((it) => ({
                name: repairItemName(String(it?.name || '').trim(), String(cat?.category || '')),
                source_text: it?.source_text ? String(it.source_text) : undefined,
                requested: Number(it?.requested ?? 1),
                sent: it?.sent ?? null,
                observation: undefined, // IA NÃO anota observação (decisão de produto) — sempre vazio
                category: String(cat?.category || '').trim()
              })) : []);
              parsedResponse.items = flattened;
              const totalItems = flattened.length;
              const totalRequested = flattened.reduce((sum, it) => sum + (Number(it.requested) || 0), 0);
              parsedResponse.meta = parsedResponse.meta || {
                total_items: totalItems,
                total_requested: totalRequested
              };
            } else if (!Array.isArray(parsedResponse?.items)) {
              parsedResponse.items = [];
              parsedResponse.categories = [];
              parsedResponse.meta = parsedResponse.meta || {
                total_items: 0,
                total_requested: 0
              };
            }
          } catch (e) { console.debug('[SSE] normalize categories skip'); }
          // Record telemetry metrics for streaming response
          if (metrics && (streamPromptTokens > 0 || streamCompletionTokens > 0)) {
            const streamDurationMs = Date.now() - streamFetchStart;
            metrics.recordLlmCall({
              model: model,
              provider: 'openrouter',
              operation: 'requisition-parse',
              inputTokens: streamPromptTokens,
              outputTokens: streamCompletionTokens,
              durationMs: streamDurationMs,
            });
          }
          sendEvent('result', { ...parsedResponse, final_model: model });
          logEvent('info', 'result_emit', { model, items: parsedResponse?.items?.length ?? 0, categories: parsedResponse?.categories?.length ?? 0, meta: parsedResponse?.meta });
          // Fire-and-forget: flush streaming telemetry
          if (tracer || metrics) {
            Promise.all([tracer?.flush(), metrics?.flush()].filter(Boolean)).catch(() => {});
          }
          controller.close();
          return;
        } catch (err) {
          sendEvent('status', {
            message: `Falha com modelo atual. Motivo: ${err instanceof Error ? err.message : String(err)}`
          });
          logEvent('warning', 'fallback_stream_error', { model, error: err instanceof Error ? err.message : String(err) });
          continue;
        }
      }
      sendEvent('error', { message: 'Streaming indisponível, retornando em modo padrão' });
      logEvent('warning', 'stream_all_failed', { models });
      controller.close();
    }
  });
  return new Response(stream, {
    headers: {
      ...corsHeaders,
      'Content-Type': 'text/event-stream',
      'Cache-Control': 'no-cache',
      'Connection': 'keep-alive',
      ...(tracer ? { 'traceparent': tracer.getResponseTraceparent() } : {}),
    }
  });
}
