    wideDebug('requisicao.ia_streaming_resposta', 'Resposta HTTP recebida', { domain: 'requisicoes', attributes: { status: response.status, statusText: response.statusText, ok: response.ok, hasBody: !!response.body } });

    if (!response.ok || !response.body) {
      const errorText = await response.text().catch(() => '');
      throw new Error(`Erro HTTP ${response.status}: ${errorText}`);
    }
    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let sseBuffer = '';
    let finished = false;
    let resultReceived = false;
    let streamErrorMsg: string | null = null;
    let eventCount = 0;
    let lastEventLogTime = 0;

    wideDebug('requisicao.ia_streaming_loop', 'Iniciando loop de leitura SSE', { domain: 'requisicoes' });

    while (!finished) {
      const { value, done } = await reader.read();
      if (done) break;
      sseBuffer += decoder.decode(value, { stream: true });
      const blocks = sseBuffer.split('\n\n');
      while (blocks.length > 1) {
        const block = blocks.shift()!;
        const lines = block.split('\n');
        let eventName = 'message';
        let dataLine = '';
        for (const line of lines) {
          if (line.startsWith('event:')) eventName = line.slice(6).trim();
          if (line.startsWith('data:')) dataLine = line.slice(5).trim();
        }

        eventCount++;
        const now = Date.now();

        // Log detalhado de cada evento (com rate limiting para nao floodar)
        if (now - lastEventLogTime > 1000 || eventCount <= 5) {
          wideDebug('requisicao.ia_streaming_evento', `Evento SSE #${eventCount}`, { domain: 'requisicoes', attributes: { event: eventName, eventCount, bufferLength: sseBuffer.length } });
          lastEventLogTime = now;
        }

        if (!dataLine || dataLine === '[DONE]') continue;
        try {
          const payload = JSON.parse(dataLine);
          if (eventName === 'status') {
            const modelStr = (payload?.model ?? payload?.message ?? '') as string;
            setCurrentAiModel(modelStr);
            setShowReasoningPanel(typeof modelStr === 'string' && modelStr.includes('deepseek/deepseek-r1'));
          }
          if (eventName === 'reasoning' && typeof currentAiModel === 'string' && currentAiModel.includes('deepseek/deepseek-r1')) {
            const txt = typeof payload?.text === 'string' ? payload.text : JSON.stringify(payload);
            wideDebug('requisicao.ia_reasoning', 'Recebido reasoning', { domain: 'requisicoes', attributes: { length: txt.length } });
            setThinkingProcess(prev => mergeStreamText(prev, txt));
          }
          if (eventName === 'reasoning_details' && typeof currentAiModel === 'string' && currentAiModel.includes('deepseek/deepseek-r1')) {
            const det = payload?.details;
            let txt = '';
            if (Array.isArray(det)) {
              txt = det.map((d: any) => (typeof d === 'string' ? d : (d.text ?? d.content ?? JSON.stringify(d)))).join('');
            } else {
              txt = typeof det === 'string' ? det : JSON.stringify(det);
            }
            wideDebug('requisicao.ia_reasoning_details', 'Recebido reasoning_details', { domain: 'requisicoes', attributes: { length: txt.length, isArray: Array.isArray(det), arrayLength: Array.isArray(det) ? det.length : 0 } });
          }
          if (eventName === 'delta') {
            setProcessingStage('Processando IA...');
            const dc = payload?.content;
            if (typeof dc === 'string' && dc.trim()) {
              wideDebug('requisicao.ia_delta', 'Recebido delta content', { domain: 'requisicoes', attributes: { length: dc.length } });
              setReasoningContent(prev => prev + dc);
            }
          }
          if (eventName === 'usage') {
            setProcessingStage('Concluindo processamento...');
            const tokens = payload?.reasoningTokens ?? payload?.reasoning_tokens ?? payload?.totalTokens ?? payload?.completionTokens ?? payload?.output_tokens;
            const n = typeof tokens === 'string' ? parseInt(tokens, 10) : tokens;

            wideDebug('requisicao.ia_usage', 'Recebido usage', { domain: 'requisicoes', attributes: { reasoningTokens: n, totalTokens: payload?.totalTokens, completionTokens: payload?.completionTokens } });

            if (typeof n === 'number' && !Number.isNaN(n)) setReasoningTokenCount(n);
          }
          if (eventName === 'result') {
            const data = payload;
            wideInfo('requisicao.ia_resultado', 'Recebido resultado final da IA', { domain: 'requisicoes', attributes: { hasItems: !!data.items, itemsCount: data.items?.length || 0, categoriesCount: data.categories?.length || 0, hasReview: !!data.meta?.synthesizer_review } });

            if (data.meta?.synthesizer_review) {
              setSynthesizerReview(data.meta.synthesizer_review);
            }

            allProcessedItems = (data.items || []).map((item: any) => ({
              ...item,
              id: generateId(),
              sent: "",
              // Texto verbatim que o usuário digitou (vindo da edge function) — usado
              // na lista de resultado p/ conferir se o match veio certo. Pode ser undefined
              // em dados antigos / quando o modelo não ecoou; UI cai no originalName.
              sourceText: item.source_text ?? undefined
            }));
            setAllItems(allProcessedItems);
            resultReceived = true;
            finished = true;
            setActiveTab('result');
          }
          if (eventName === 'error') {
            // A edge function emite 'error' (modelo falhou, JSON inválido, streaming
            // indisponível) e fecha o stream. Antes isso era IGNORADO e o fluxo seguia
            // fingindo sucesso → tela vazia sem erro. Agora capturamos e abortamos.
            streamErrorMsg = String(payload?.message || payload?.error || 'A IA falhou ao processar a requisição');
            finished = true;
          }
        } catch (parseError) {
          wideWarn('requisicao.ia_streaming_parse_erro', 'Erro ao parsear evento SSE', { domain: 'requisicoes', attributes: { eventName, dataLine } });
        }
      }
      sseBuffer = blocks[0] || '';
    }
    if (streamAbortTimer) { clearTimeout(streamAbortTimer); streamAbortTimer = null; }
    // Falha real: stream com 'error' ou que terminou sem 'result'. NUNCA seguir pra
    // validação com lista vazia fingindo sucesso (causa raiz da "tela vazia sem erro").
    if (streamErrorMsg) {
      throw new Error(streamErrorMsg);
    }
    if (!resultReceived) {
      throw new Error('A IA não retornou resultado (conexão encerrada antes do fim). Tente novamente.');
    }
  } catch (networkError) {
    if (streamAbortTimer) { clearTimeout(streamAbortTimer); streamAbortTimer = null; }
    handleError(networkError, { domain: 'requisicoes', operation: 'iaStreamingConexao', showToast: false });
    throw networkError;
  }
}

// Finalização
setProcessingStage('Finalizando...');
setProcessingProgress(100);
await new Promise(resolve => setTimeout(resolve, 400));

