}

function logEvent(level: 'info' | 'warning' | 'error', event: string, data: Record<string, unknown> = {}) {
  const payload = { ts: new Date().toISOString(), function: 'process-requisition-ai', event, ...data };
  if (level === 'error') console.error('[AI]', JSON.stringify(payload));
  else if (level === 'warning') console.warn('[AI]', JSON.stringify(payload));
