2	 * Telemetria OpenTelemetry leve para Supabase Edge Functions (Deno).
3	 *
4	 * - Parse do header W3C `traceparent` para correlação com o frontend
5	 * - Criação de spans estruturados para as fases da requisição
6	 * - Métricas de tokens IA (Counters + Histograms) via OTLP/HTTP
7	 * - Exportação via OTLP/HTTP (JSON)
8	 * - Zero overhead quando desabilitado (OTEL_ENABLED !== 'true')
9	 *
10	 * Variáveis de ambiente:
11	 *   OTEL_ENABLED          — 'true' para habilitar (padrão: 'false')
12	 *   OTEL_ENDPOINT         — URL do collector OTLP (padrão: 'http://localhost:4318')
13	 *   OTEL_SERVICE_NAME     — nome do serviço (padrão: 'gidape-edge-requisicao-ia')
14	 *   OTEL_SERVICE_VERSION  — versão do serviço (padrão: '0.0.0')
15	 *   OTEL_ENVIRONMENT      — ambiente: dev, staging, prod (padrão: 'dev')
16	 */
17	
18	// ---------------------------------------------------------------------------
19	// Configuração
20	// ---------------------------------------------------------------------------
21	
22	export interface EdgeTelemetryConfig {
23	  enabled: boolean;
24	  endpoint: string;
25	  serviceName: string;
26	  serviceVersion: string;
27	  environment: string;
28	}
29	
30	export function getEdgeTelemetryConfig(): EdgeTelemetryConfig {
31	  return {
32	    enabled: Deno.env.get('OTEL_ENABLED') === 'true',
33	    endpoint: Deno.env.get('OTEL_ENDPOINT') || 'http://localhost:4318',
34	    serviceName: Deno.env.get('OTEL_SERVICE_NAME') || 'gidape-edge-requisicao-ia',
35	    serviceVersion: Deno.env.get('OTEL_SERVICE_VERSION') || '0.0.0',
36	    environment: Deno.env.get('OTEL_ENVIRONMENT') || 'dev',
37	  };
38	}
39	
40	// ---------------------------------------------------------------------------
41	// W3C Traceparent — parse e geração
42	// ---------------------------------------------------------------------------
43	
44	export interface TraceParent {
45	  version: string;
46	  traceId: string;
47	  parentSpanId: string;
48	  traceFlags: number;
49	}
50	
51	/**
52	 * Parse do header W3C traceparent.
53	 * Formato: {version}-{trace-id}-{parent-id}-{trace-flags}
54	 * Exemplo: 00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01
55	 */
56	export function parseTraceparent(header: string | null): TraceParent | null {
57	  if (!header) return null;
58	  const parts = header.trim().split('-');
59	  if (parts.length !== 4) return null;
60	
61	  const [version, traceId, parentSpanId, flagsHex] = parts;
62	
63	  // Validar formato
64	  if (version.length !== 2 || traceId.length !== 32 || parentSpanId.length !== 16 || flagsHex.length !== 2) {
65	    return null;
66	  }
67	
68	  // trace_id todo zero é inválido
69	  if (/^0+$/.test(traceId)) return null;
70	
71	  return {
72	    version,
73	    traceId,
74	    parentSpanId,
75	    traceFlags: parseInt(flagsHex, 16),
76	  };
77	}
78	
79	/**
80	 * Gera um ID hexadecimal aleatório com o comprimento especificado.
81	 */
82	export function generateHexId(bytes: number): string {
83	  const array = new Uint8Array(bytes);
84	  crypto.getRandomValues(array);
85	  return Array.from(array, (b) => b.toString(16).padStart(2, '0')).join('');
86	}
87	
88	/**
89	 * Gera um novo trace_id (16 bytes = 32 hex chars).
90	 */
91	export function generateTraceId(): string {
92	  return generateHexId(16);
93	}
94	
95	/**
96	 * Gera um novo span_id (8 bytes = 16 hex chars).
97	 */
98	export function generateSpanId(): string {
99	  return generateHexId(8);
100	}
101	
102	/**
103	 * Formata um traceparent header W3C.
104	 */
105	export function formatTraceparent(traceId: string, spanId: string, sampled: boolean = true): string {
106	  return `00-${traceId}-${spanId}-${sampled ? '01' : '00'}`;
107	}
108	
109	// ---------------------------------------------------------------------------
110	// Span — representação de um span OTLP
111	// ---------------------------------------------------------------------------
112	
113	export interface SpanData {
114	  traceId: string;
115	  spanId: string;
116	  parentSpanId: string;
117	  name: string;
118	  kind: number; // 0=INTERNAL, 1=SERVER, 2=CLIENT
119	  startTimeUnixNano: bigint;
120	  endTimeUnixNano: bigint;
121	  attributes: Array<{ key: string; value: { stringValue?: string; intValue?: number; doubleValue?: number; boolValue?: boolean } }>;
122	  status: { code: number; message?: string }; // 0=UNSET, 1=OK, 2=ERROR
123	  events: Array<{ name: string; timeUnixNano: bigint; attributes: SpanData['attributes'] }>;
124	}
125	
126	// ---------------------------------------------------------------------------
127	// EdgeTracer — instrumentação leve
128	// ---------------------------------------------------------------------------
129	
130	export interface EdgeSpan {
131	  /** Adiciona atributo ao span */
132	  setAttribute(key: string, value: string | number | boolean): void;
133	  /** Registra evento no span */
134	  addEvent(name: string, attributes?: Record<string, string | number | boolean>): void;
135	  /** Finaliza o span com sucesso */
136	  end(): void;
137	  /** Finaliza o span com erro */
138	  endWithError(message: string): void;
139	  /** ID do span */
140	  readonly spanId: string;
141	}
142	
143	export class EdgeTracer {
144	  private readonly config: EdgeTelemetryConfig;
145	  private readonly traceId: string;
146	  private readonly rootSpanId: string;
147	  private readonly spans: SpanData[] = [];
148	  private readonly enabled: boolean;
149	
150	  constructor(req: Request, configOverride?: Partial<EdgeTelemetryConfig>) {
151	    this.config = { ...getEdgeTelemetryConfig(), ...configOverride };
152	    this.enabled = this.config.enabled;
153	
154	    // Correlacionar com o frontend via traceparent
155	    const traceparent = parseTraceparent(req.headers.get('traceparent'));
156	    if (traceparent) {
157	      this.traceId = traceparent.traceId;
158	      this.rootSpanId = traceparent.parentSpanId;
159	    } else {
160	      this.traceId = generateTraceId();
161	      this.rootSpanId = generateSpanId();
162	    }
163	  }
164	
165	  /** Retorna o trace_id atual (para logs/correlação) */
166	  getTraceId(): string {
167	    return this.traceId;
168	  }
169	
170	  /** Retorna o traceparent formatado para headers de resposta */
171	  getResponseTraceparent(): string {
172	    return formatTraceparent(this.traceId, this.rootSpanId);
173	  }
174	
175	  /**
176	   * Inicia um novo span.
177	   * Retorna um EdgeSpan que deve ser finalizado com end() ou endWithError().
178	   */
179	  startSpan(name: string, parentSpanId?: string): EdgeSpan {
180	    if (!this.enabled) {
181	      return this.createNoopSpan();
182	    }
183	
184	    const spanId = generateSpanId();
185	    const startTime = BigInt(Date.now()) * 1_000_000n; // ms → ns
186	    const attributes: SpanData['attributes'] = [];
187	    const events: SpanData['events'] = [];
188	    let ended = false;
189	
190	    const span: EdgeSpan = {
191	      spanId,
192	      setAttribute: (key: string, value: string | number | boolean) => {
193	        if (ended) return;
194	        const attr: SpanData['attributes'][0] = { key, value: {} };
195	        if (typeof value === 'string') attr.value.stringValue = value;
196	        else if (typeof value === 'boolean') attr.value.boolValue = value;
197	        else if (Number.isInteger(value)) attr.value.intValue = value as number;
198	        else attr.value.doubleValue = value as number;
199	        attributes.push(attr);
200	      },
201	      addEvent: (eventName: string, eventAttrs?: Record<string, string | number | boolean>) => {
202	        if (ended) return;
203	        const otelAttrs: SpanData['attributes'] = [];
204	        if (eventAttrs) {
205	          for (const [k, v] of Object.entries(eventAttrs)) {
206	            const attr: SpanData['attributes'][0] = { key: k, value: {} };
207	            if (typeof v === 'string') attr.value.stringValue = v;
208	            else if (typeof v === 'boolean') attr.value.boolValue = v;
209	            else if (Number.isInteger(v)) attr.value.intValue = v as number;
210	            else attr.value.doubleValue = v as number;
211	            otelAttrs.push(attr);
212	          }
213	        }
214	        events.push({
215	          name: eventName,
216	          timeUnixNano: BigInt(Date.now()) * 1_000_000n,
217	          attributes: otelAttrs,
218	        });
219	      },
220	      end: () => {
221	        if (ended) return;
222	        ended = true;
223	        const endTime = BigInt(Date.now()) * 1_000_000n;
224	        this.spans.push({
225	          traceId: this.traceId,
226	          spanId,
227	          parentSpanId: parentSpanId || this.rootSpanId,
228	          name,
229	          kind: parentSpanId ? 0 : 1, // SERVER para root, INTERNAL para filhos
230	          startTimeUnixNano: startTime,
231	          endTimeUnixNano: endTime,
232	          attributes,
233	          status: { code: 1 }, // OK
234	          events,
235	        });
236	      },
237	      endWithError: (message: string) => {
238	        if (ended) return;
239	        ended = true;
240	        const endTime = BigInt(Date.now()) * 1_000_000n;
241	        this.spans.push({
242	          traceId: this.traceId,
243	          spanId,
244	          parentSpanId: parentSpanId || this.rootSpanId,
245	          name,
246	          kind: parentSpanId ? 0 : 1,
247	          startTimeUnixNano: startTime,
248	          endTimeUnixNano: endTime,
249	          attributes,
250	          status: { code: 2, message }, // ERROR
251	          events,
252	        });
253	      },
254	    };
255	
256	    return span;
257	  }
258	
259	  /**
260	   * Exporta todos os spans coletados via OTLP/HTTP.
261	   * Chamado no final da requisição (fire-and-forget).
262	   */
263	  async flush(): Promise<void> {
264	    if (!this.enabled || this.spans.length === 0) return;
265	
266	    const payload = {
267	      resourceSpans: [{
268	        resource: {
269	          attributes: [
270	            { key: 'service.name', value: { stringValue: this.config.serviceName } },
271	            { key: 'service.version', value: { stringValue: this.config.serviceVersion } },
272	            { key: 'deployment.environment.name', value: { stringValue: this.config.environment } },
273	          ],
274	        },
275	        scopeSpans: [{
276	          scope: { name: 'gidape-edge-function', version: '1.0.0' },
277	          spans: this.spans.map(s => ({
278	            traceId: s.traceId,
279	            spanId: s.spanId,
280	            parentSpanId: s.parentSpanId,
281	            name: s.name,
282	            kind: s.kind,
283	            startTimeUnixNano: s.startTimeUnixNano.toString(),
284	            endTimeUnixNano: s.endTimeUnixNano.toString(),
285	            attributes: s.attributes,
286	            status: s.status,
287	            events: s.events.map(e => ({
288	              ...e,
289	              timeUnixNano: e.timeUnixNano.toString(),
290	            })),
291	          })),
292	        }],
293	      }],
294	    };
295	
296	    try {
297	      await fetch(`${this.config.endpoint}/v1/traces`, {
298	        method: 'POST',
299	        headers: { 'Content-Type': 'application/json' },
300	        body: JSON.stringify(payload),
301	      });
302	    } catch (err) {
303	      // Falha silenciosa — telemetria não deve quebrar a Edge Function
304	      console.warn('[Telemetry] Falha ao exportar spans:', err instanceof Error ? err.message : err);
305	    }
306	  }
307	
308	  // ---------------------------------------------------------------------------
309	  // Noop span — zero overhead quando desabilitado
310	  // ---------------------------------------------------------------------------
311	
312	  private createNoopSpan(): EdgeSpan {
313	    return {
314	      spanId: '0'.repeat(16),
315	      setAttribute: () => {},
316	      addEvent: () => {},
317	      end: () => {},
318	      endWithError: () => {},
319	    };
320	  }
321	}
322	
323	// ---------------------------------------------------------------------------
324	// Métricas OTLP — Counters e Histograms para tokens IA
325	// ---------------------------------------------------------------------------
326	
327	interface MetricDataPoint {
328	  attributes: Array<{ key: string; value: { stringValue?: string; intValue?: number; doubleValue?: number } }>;
329	  startTimeUnixNano: string;
330	  timeUnixNano: string;
331	  asInt?: string;
332	  asDouble?: number;
333	}
334	
335	interface SumMetric {
336	  name: string;
337	  unit: string;
338	  sum: {
339	    dataPoints: MetricDataPoint[];
340	    aggregationTemporality: number; // 2 = DELTA
341	    isMonotonic: boolean;
342	  };
343	}
344	
345	interface HistogramDataPoint {
346	  attributes: MetricDataPoint['attributes'];
347	  startTimeUnixNano: string;
348	  timeUnixNano: string;
349	  count: string;
350	  sum: number;
351	  min: number;
352	  max: number;
353	  bucketCounts: string[];
354	  explicitBounds: number[];
355	}
356	
357	interface HistogramMetric {
358	  name: string;
359	  unit: string;
360	  histogram: {
361	    dataPoints: HistogramDataPoint[];
362	    aggregationTemporality: number;
363	  };
364	}
365	
366	function toOtelAttributes(attrs: Record<string, string | number>): MetricDataPoint['attributes'] {
367	  return Object.entries(attrs).map(([key, value]) => ({
368	    key,
369	    value: typeof value === 'string'
370	      ? { stringValue: value }
371	      : Number.isInteger(value) ? { intValue: value } : { doubleValue: value },
372	  }));
373	}
374	
375	/**
376	 * Tabela de custo estimado por modelo (USD por 1M tokens).
377	 * Fonte: OpenRouter pricing. Modelos :free custam $0.
378	 */
379	const MODEL_COST_PER_1M: Record<string, { input: number; output: number }> = {
380	  'deepseek/deepseek-r1-0528:free': { input: 0, output: 0 },
381	  'openai/gpt-oss-120b:free': { input: 0, output: 0 },
382	  'x-ai/grok-4.1-fast:free': { input: 0, output: 0 },
383	  'x-ai/grok-4.1-fast': { input: 3, output: 15 },
384	  'x-ai/grok-4-fast': { input: 3, output: 15 },
385	  'deepseek/deepseek-r1-distill-llama-70b:free': { input: 0, output: 0 },
386	  'google/gemini-2.0-flash-001': { input: 0.1, output: 0.4 },
387	};
388	
389	function estimateCostUsd(model: string, inputTokens: number, outputTokens: number): number {
390	  const pricing = MODEL_COST_PER_1M[model];
391	  if (!pricing) return 0;
392	  return (inputTokens / 1_000_000) * pricing.input + (outputTokens / 1_000_000) * pricing.output;
393	}
394	
395	/**
396	 * Coletor de métricas OTLP para Edge Functions.
397	 * Acumula data points durante a requisição e exporta via OTLP/HTTP no flush.
398	 */
399	export class EdgeMetrics {
400	  private readonly config: EdgeTelemetryConfig;
401	  private readonly enabled: boolean;
402	  private readonly startTimeNano: string;
403	  private readonly counters: Map<string, { unit: string; dataPoints: MetricDataPoint[] }> = new Map();
404	  private readonly histograms: Map<string, { unit: string; bounds: number[]; dataPoints: HistogramDataPoint[] }> = new Map();
405	
406	  constructor(configOverride?: Partial<EdgeTelemetryConfig>) {
407	    this.config = { ...getEdgeTelemetryConfig(), ...configOverride };
408	    this.enabled = this.config.enabled;
409	    this.startTimeNano = (BigInt(Date.now()) * 1_000_000n).toString();
410	  }
411	
412	  /**
413	   * Incrementa um counter com o valor e atributos dados.
414	   */
415	  addCounter(name: string, value: number, attributes: Record<string, string | number>, unit = '1'): void {
416	    if (!this.enabled) return;
417	
418	    if (!this.counters.has(name)) {
419	      this.counters.set(name, { unit, dataPoints: [] });
420	    }
421	
422	    this.counters.get(name)!.dataPoints.push({
423	      attributes: toOtelAttributes(attributes),
424	      startTimeUnixNano: this.startTimeNano,
425	      timeUnixNano: (BigInt(Date.now()) * 1_000_000n).toString(),
426	      asInt: String(Math.round(value)),
427	    });
428	  }
429	
430	  /**
431	   * Registra um valor em um histogram.
432	   */
433	  recordHistogram(
434	    name: string,
435	    value: number,
436	    attributes: Record<string, string | number>,
437	    unit = 'ms',
438	    bounds = [50, 100, 250, 500, 1000, 2500, 5000, 10000, 30000, 60000],
439	  ): void {
440	    if (!this.enabled) return;
441	
442	    if (!this.histograms.has(name)) {
443	      this.histograms.set(name, { unit, bounds, dataPoints: [] });
444	    }
445	
446	    const bucketCounts = new Array(bounds.length + 1).fill(0);
447	    for (let i = 0; i < bounds.length; i++) {
448	      if (value <= bounds[i]) { bucketCounts[i]++; break; }
449	      if (i === bounds.length - 1) bucketCounts[bounds.length]++;
450	    }
451	
452	    this.histograms.get(name)!.dataPoints.push({
453	      attributes: toOtelAttributes(attributes),
454	      startTimeUnixNano: this.startTimeNano,
455	      timeUnixNano: (BigInt(Date.now()) * 1_000_000n).toString(),
456	      count: '1',
457	      sum: value,
458	      min: value,
459	      max: value,
460	      bucketCounts: bucketCounts.map(String),
461	      explicitBounds: bounds,
462	    });
463	  }
464	
465	  /**
466	   * Registra métricas de uma chamada LLM.
467	   * Emite: tokens.input, tokens.output, tokens.total, request.duration, request.cost
468	   */
469	  recordLlmCall(params: {
470	    model: string;
471	    provider: string;
472	    operation: string;
473	    unidadeNome?: string;
474	    inputTokens: number;
475	    outputTokens: number;
476	    durationMs: number;
477	  }): void {
478	    if (!this.enabled) return;
479	
480	    const { model, provider, operation, unidadeNome, inputTokens, outputTokens, durationMs } = params;
481	    const totalTokens = inputTokens + outputTokens;
482	    const costUsd = estimateCostUsd(model, inputTokens, outputTokens);
483	
484	    const attrs: Record<string, string | number> = {
485	      'model.name': model,
486	      'model.provider': provider,
487	      'operation': operation,
488	    };
489	    if (unidadeNome) attrs['unidade.nome'] = unidadeNome;
490	
491	    this.addCounter('app.ai.tokens.input', inputTokens, attrs, '{tokens}');
492	    this.addCounter('app.ai.tokens.output', outputTokens, attrs, '{tokens}');
493	    this.addCounter('app.ai.tokens.total', totalTokens, attrs, '{tokens}');
494	    this.addCounter('app.ai.request.cost', costUsd, { ...attrs, 'cost.currency': 'USD' }, 'USD');
495	    this.recordHistogram('app.ai.request.duration', durationMs, attrs, 'ms');
496	  }
497	
498	  /**
499	   * Exporta todas as métricas coletadas via OTLP/HTTP.
500	   */
501	  async flush(): Promise<void> {
502	    if (!this.enabled) return;
503	    if (this.counters.size === 0 && this.histograms.size === 0) return;
504	
505	    const metrics: (SumMetric | HistogramMetric)[] = [];
506	
507	    for (const [name, { unit, dataPoints }] of this.counters) {
508	      metrics.push({
509	        name,
510	        unit,
511	        sum: { dataPoints, aggregationTemporality: 2, isMonotonic: true },
512	      });
513	    }
514	
515	    for (const [name, { unit, dataPoints }] of this.histograms) {
516	      metrics.push({
517	        name,
518	        unit,
519	        histogram: { dataPoints, aggregationTemporality: 2 },
520	      });
521	    }
522	
523	    const payload = {
524	      resourceMetrics: [{
525	        resource: {
526	          attributes: [
527	            { key: 'service.name', value: { stringValue: this.config.serviceName } },
528	            { key: 'service.version', value: { stringValue: this.config.serviceVersion } },
529	            { key: 'deployment.environment.name', value: { stringValue: this.config.environment } },
530	          ],
531	        },
532	        scopeMetrics: [{
533	          scope: { name: 'gidape-edge-function', version: '1.0.0' },
534	          metrics,
535	        }],
536	      }],
537	    };
538	
539	    try {
540	      await fetch(`${this.config.endpoint}/v1/metrics`, {
541	        method: 'POST',
542	        headers: { 'Content-Type': 'application/json' },
543	        body: JSON.stringify(payload),
544	      });
545	    } catch (err) {
546	      console.warn('[Telemetry] Falha ao exportar métricas:', err instanceof Error ? err.message : err);
547	    }
548	  }
549	}
550	
551	/**
552	 * Resultado de uma chamada LLM com dados de usage.
553	 */
554	export interface LlmCallResult {
555	  content: string;
556	  toolCalls?: any[];
557	  usage: {
558	    promptTokens: number;
559	    completionTokens: number;
560	    totalTokens: number;
561	  };
562	  model: string;
563	}
