/**
 * Telemetria OpenTelemetry leve para Supabase Edge Functions (Deno).
 *
 * - Parse do header W3C `traceparent` para correlação com o frontend
 * - Criação de spans estruturados para as fases da requisição
 * - Métricas de tokens IA (Counters + Histograms) via OTLP/HTTP
 * - Exportação via OTLP/HTTP (JSON)
 * - Zero overhead quando desabilitado (OTEL_ENABLED !== 'true')
 *
 * Variáveis de ambiente:
 *   OTEL_ENABLED          — 'true' para habilitar (padrão: 'false')
 *   OTEL_ENDPOINT         — URL do collector OTLP (padrão: 'http://localhost:4318')
 *   OTEL_SERVICE_NAME     — nome do serviço (padrão: 'gidape-edge-requisicao-ia')
 *   OTEL_SERVICE_VERSION  — versão do serviço (padrão: '0.0.0')
 *   OTEL_ENVIRONMENT      — ambiente: dev, staging, prod (padrão: 'dev')
 */

// ---------------------------------------------------------------------------
// Configuração
// ---------------------------------------------------------------------------

export interface EdgeTelemetryConfig {
  enabled: boolean;
  endpoint: string;
  serviceName: string;
  serviceVersion: string;
  environment: string;
}

export function getEdgeTelemetryConfig(): EdgeTelemetryConfig {
  return {
    enabled: Deno.env.get('OTEL_ENABLED') === 'true',
    endpoint: Deno.env.get('OTEL_ENDPOINT') || 'http://localhost:4318',
    serviceName: Deno.env.get('OTEL_SERVICE_NAME') || 'gidape-edge-requisicao-ia',
    serviceVersion: Deno.env.get('OTEL_SERVICE_VERSION') || '0.0.0',
    environment: Deno.env.get('OTEL_ENVIRONMENT') || 'dev',
  };
}

// ---------------------------------------------------------------------------
// W3C Traceparent — parse e geração
// ---------------------------------------------------------------------------

export interface TraceParent {
  version: string;
  traceId: string;
  parentSpanId: string;
  traceFlags: number;
}

/**
 * Parse do header W3C traceparent.
 * Formato: {version}-{trace-id}-{parent-id}-{trace-flags}
 * Exemplo: 00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01
 */
export function parseTraceparent(header: string | null): TraceParent | null {
  if (!header) return null;
  const parts = header.trim().split('-');
  if (parts.length !== 4) return null;

  const [version, traceId, parentSpanId, flagsHex] = parts;

  // Validar formato
  if (version.length !== 2 || traceId.length !== 32 || parentSpanId.length !== 16 || flagsHex.length !== 2) {
    return null;
  }

  // trace_id todo zero é inválido
  if (/^0+$/.test(traceId)) return null;

  return {
    version,
    traceId,
    parentSpanId,
    traceFlags: parseInt(flagsHex, 16),
  };
}

/**
 * Gera um ID hexadecimal aleatório com o comprimento especificado.
 */
export function generateHexId(bytes: number): string {
  const array = new Uint8Array(bytes);
  crypto.getRandomValues(array);
  return Array.from(array, (b) => b.toString(16).padStart(2, '0')).join('');
}

/**
 * Gera um novo trace_id (16 bytes = 32 hex chars).
 */
export function generateTraceId(): string {
  return generateHexId(16);
}

/**
 * Gera um novo span_id (8 bytes = 16 hex chars).
 */
export function generateSpanId(): string {
  return generateHexId(8);
}

/**
 * Formata um traceparent header W3C.
 */
export function formatTraceparent(traceId: string, spanId: string, sampled: boolean = true): string {
  return `00-${traceId}-${spanId}-${sampled ? '01' : '00'}`;
}

// ---------------------------------------------------------------------------
// Span — representação de um span OTLP
// ---------------------------------------------------------------------------

export interface SpanData {
  traceId: string;
  spanId: string;
  parentSpanId: string;
  name: string;
  kind: number; // 0=INTERNAL, 1=SERVER, 2=CLIENT
  startTimeUnixNano: bigint;
  endTimeUnixNano: bigint;
  attributes: Array<{ key: string; value: { stringValue?: string; intValue?: number; doubleValue?: number; boolValue?: boolean } }>;
  status: { code: number; message?: string }; // 0=UNSET, 1=OK, 2=ERROR
  events: Array<{ name: string; timeUnixNano: bigint; attributes: SpanData['attributes'] }>;
}

// ---------------------------------------------------------------------------
// EdgeTracer — instrumentação leve
// ---------------------------------------------------------------------------

export interface EdgeSpan {
  /** Adiciona atributo ao span */
  setAttribute(key: string, value: string | number | boolean): void;
  /** Registra evento no span */
  addEvent(name: string, attributes?: Record<string, string | number | boolean>): void;
  /** Finaliza o span com sucesso */
  end(): void;
  /** Finaliza o span com erro */
  endWithError(message: string): void;
  /** ID do span */
  readonly spanId: string;
}

export class EdgeTracer {
  private readonly config: EdgeTelemetryConfig;
  private readonly traceId: string;
  private readonly rootSpanId: string;
  private readonly spans: SpanData[] = [];
  private readonly enabled: boolean;

  constructor(req: Request, configOverride?: Partial<EdgeTelemetryConfig>) {
    this.config = { ...getEdgeTelemetryConfig(), ...configOverride };
    this.enabled = this.config.enabled;

    // Correlacionar com o frontend via traceparent
    const traceparent = parseTraceparent(req.headers.get('traceparent'));
    if (traceparent) {
      this.traceId = traceparent.traceId;
      this.rootSpanId = traceparent.parentSpanId;
    } else {
      this.traceId = generateTraceId();
      this.rootSpanId = generateSpanId();
    }
  }

  /** Retorna o trace_id atual (para logs/correlação) */
  getTraceId(): string {
    return this.traceId;
  }

  /** Retorna o traceparent formatado para headers de resposta */
  getResponseTraceparent(): string {
    return formatTraceparent(this.traceId, this.rootSpanId);
  }

  /**
   * Inicia um novo span.
   * Retorna um EdgeSpan que deve ser finalizado com end() ou endWithError().
   */
  startSpan(name: string, parentSpanId?: string): EdgeSpan {
    if (!this.enabled) {
      return this.createNoopSpan();
    }

    const spanId = generateSpanId();
    const startTime = BigInt(Date.now()) * 1_000_000n; // ms → ns
    const attributes: SpanData['attributes'] = [];
    const events: SpanData['events'] = [];
    let ended = false;

    const span: EdgeSpan = {
      spanId,
      setAttribute: (key: string, value: string | number | boolean) => {
        if (ended) return;
        const attr: SpanData['attributes'][0] = { key, value: {} };
        if (typeof value === 'string') attr.value.stringValue = value;
        else if (typeof value === 'boolean') attr.value.boolValue = value;
        else if (Number.isInteger(value)) attr.value.intValue = value as number;
        else attr.value.doubleValue = value as number;
        attributes.push(attr);
      },
      addEvent: (eventName: string, eventAttrs?: Record<string, string | number | boolean>) => {
        if (ended) return;
        const otelAttrs: SpanData['attributes'] = [];
        if (eventAttrs) {
          for (const [k, v] of Object.entries(eventAttrs)) {
            const attr: SpanData['attributes'][0] = { key: k, value: {} };
            if (typeof v === 'string') attr.value.stringValue = v;
            else if (typeof v === 'boolean') attr.value.boolValue = v;
            else if (Number.isInteger(v)) attr.value.intValue = v as number;
            else attr.value.doubleValue = v as number;
            otelAttrs.push(attr);
          }
        }
        events.push({
          name: eventName,
          timeUnixNano: BigInt(Date.now()) * 1_000_000n,
          attributes: otelAttrs,
        });
      },
      end: () => {
        if (ended) return;
        ended = true;
        const endTime = BigInt(Date.now()) * 1_000_000n;
        this.spans.push({
          traceId: this.traceId,
          spanId,
          parentSpanId: parentSpanId || this.rootSpanId,
          name,
          kind: parentSpanId ? 0 : 1, // SERVER para root, INTERNAL para filhos
          startTimeUnixNano: startTime,
          endTimeUnixNano: endTime,
          attributes,
          status: { code: 1 }, // OK
          events,
        });
      },
      endWithError: (message: string) => {
        if (ended) return;
        ended = true;
        const endTime = BigInt(Date.now()) * 1_000_000n;
        this.spans.push({
          traceId: this.traceId,
          spanId,
          parentSpanId: parentSpanId || this.rootSpanId,
          name,
          kind: parentSpanId ? 0 : 1,
          startTimeUnixNano: startTime,
          endTimeUnixNano: endTime,
          attributes,
          status: { code: 2, message }, // ERROR
          events,
        });
      },
    };

    return span;
  }

  /**
   * Exporta todos os spans coletados via OTLP/HTTP.
   * Chamado no final da requisição (fire-and-forget).
   */
  async flush(): Promise<void> {
    if (!this.enabled || this.spans.length === 0) return;

    const payload = {
      resourceSpans: [{
        resource: {
          attributes: [
            { key: 'service.name', value: { stringValue: this.config.serviceName } },
            { key: 'service.version', value: { stringValue: this.config.serviceVersion } },
            { key: 'deployment.environment.name', value: { stringValue: this.config.environment } },
          ],
        },
        scopeSpans: [{
          scope: { name: 'gidape-edge-function', version: '1.0.0' },
          spans: this.spans.map(s => ({
            traceId: s.traceId,
            spanId: s.spanId,
            parentSpanId: s.parentSpanId,
            name: s.name,
            kind: s.kind,
            startTimeUnixNano: s.startTimeUnixNano.toString(),
            endTimeUnixNano: s.endTimeUnixNano.toString(),
            attributes: s.attributes,
            status: s.status,
            events: s.events.map(e => ({
              ...e,
              timeUnixNano: e.timeUnixNano.toString(),
            })),
          })),
        }],
      }],
    };

    try {
      await fetch(`${this.config.endpoint}/v1/traces`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });
    } catch (err) {
      // Falha silenciosa — telemetria não deve quebrar a Edge Function
      console.warn('[Telemetry] Falha ao exportar spans:', err instanceof Error ? err.message : err);
    }
  }

  // ---------------------------------------------------------------------------
  // Noop span — zero overhead quando desabilitado
  // ---------------------------------------------------------------------------

  private createNoopSpan(): EdgeSpan {
    return {
      spanId: '0'.repeat(16),
      setAttribute: () => {},
      addEvent: () => {},
      end: () => {},
      endWithError: () => {},
    };
  }
}

// ---------------------------------------------------------------------------
// Métricas OTLP — Counters e Histograms para tokens IA
// ---------------------------------------------------------------------------

interface MetricDataPoint {
  attributes: Array<{ key: string; value: { stringValue?: string; intValue?: number; doubleValue?: number } }>;
  startTimeUnixNano: string;
  timeUnixNano: string;
  asInt?: string;
  asDouble?: number;
}

interface SumMetric {
  name: string;
  unit: string;
  sum: {
    dataPoints: MetricDataPoint[];
    aggregationTemporality: number; // 2 = DELTA
    isMonotonic: boolean;
  };
}

interface HistogramDataPoint {
  attributes: MetricDataPoint['attributes'];
  startTimeUnixNano: string;
  timeUnixNano: string;
  count: string;
  sum: number;
  min: number;
  max: number;
  bucketCounts: string[];
  explicitBounds: number[];
}

interface HistogramMetric {
  name: string;
  unit: string;
  histogram: {
    dataPoints: HistogramDataPoint[];
    aggregationTemporality: number;
  };
}

function toOtelAttributes(attrs: Record<string, string | number>): MetricDataPoint['attributes'] {
  return Object.entries(attrs).map(([key, value]) => ({
    key,
    value: typeof value === 'string'
      ? { stringValue: value }
      : Number.isInteger(value) ? { intValue: value } : { doubleValue: value },
  }));
}

/**
 * Tabela de custo estimado por modelo (USD por 1M tokens).
 * Fonte: OpenRouter pricing. Modelos :free custam $0.
 */
const MODEL_COST_PER_1M: Record<string, { input: number; output: number }> = {
  'deepseek/deepseek-r1-0528:free': { input: 0, output: 0 },
  'openai/gpt-oss-120b:free': { input: 0, output: 0 },
  'x-ai/grok-4.1-fast:free': { input: 0, output: 0 },
  'x-ai/grok-4.1-fast': { input: 3, output: 15 },
  'x-ai/grok-4-fast': { input: 3, output: 15 },
  'deepseek/deepseek-r1-distill-llama-70b:free': { input: 0, output: 0 },
  'google/gemini-2.0-flash-001': { input: 0.1, output: 0.4 },
};

function estimateCostUsd(model: string, inputTokens: number, outputTokens: number): number {
  const pricing = MODEL_COST_PER_1M[model];
  if (!pricing) return 0;
  return (inputTokens / 1_000_000) * pricing.input + (outputTokens / 1_000_000) * pricing.output;
}

/**
 * Coletor de métricas OTLP para Edge Functions.
 * Acumula data points durante a requisição e exporta via OTLP/HTTP no flush.
 */
export class EdgeMetrics {
  private readonly config: EdgeTelemetryConfig;
  private readonly enabled: boolean;
  private readonly startTimeNano: string;
  private readonly counters: Map<string, { unit: string; dataPoints: MetricDataPoint[] }> = new Map();
  private readonly histograms: Map<string, { unit: string; bounds: number[]; dataPoints: HistogramDataPoint[] }> = new Map();

  constructor(configOverride?: Partial<EdgeTelemetryConfig>) {
    this.config = { ...getEdgeTelemetryConfig(), ...configOverride };
    this.enabled = this.config.enabled;
    this.startTimeNano = (BigInt(Date.now()) * 1_000_000n).toString();
  }

  /**
   * Incrementa um counter com o valor e atributos dados.
   */
  addCounter(name: string, value: number, attributes: Record<string, string | number>, unit = '1'): void {
    if (!this.enabled) return;

    if (!this.counters.has(name)) {
      this.counters.set(name, { unit, dataPoints: [] });
    }

    this.counters.get(name)!.dataPoints.push({
      attributes: toOtelAttributes(attributes),
      startTimeUnixNano: this.startTimeNano,
      timeUnixNano: (BigInt(Date.now()) * 1_000_000n).toString(),
      asInt: String(Math.round(value)),
    });
  }

  /**
   * Registra um valor em um histogram.
   */
  recordHistogram(
    name: string,
    value: number,
    attributes: Record<string, string | number>,
    unit = 'ms',
    bounds = [50, 100, 250, 500, 1000, 2500, 5000, 10000, 30000, 60000],
  ): void {
    if (!this.enabled) return;

    if (!this.histograms.has(name)) {
      this.histograms.set(name, { unit, bounds, dataPoints: [] });
    }

    const bucketCounts = new Array(bounds.length + 1).fill(0);
    for (let i = 0; i < bounds.length; i++) {
      if (value <= bounds[i]) { bucketCounts[i]++; break; }
      if (i === bounds.length - 1) bucketCounts[bounds.length]++;
    }

    this.histograms.get(name)!.dataPoints.push({
      attributes: toOtelAttributes(attributes),
      startTimeUnixNano: this.startTimeNano,
      timeUnixNano: (BigInt(Date.now()) * 1_000_000n).toString(),
      count: '1',
      sum: value,
      min: value,
      max: value,
      bucketCounts: bucketCounts.map(String),
      explicitBounds: bounds,
    });
  }

  /**
   * Registra métricas de uma chamada LLM.
   * Emite: tokens.input, tokens.output, tokens.total, request.duration, request.cost
   */
  recordLlmCall(params: {
    model: string;
    provider: string;
    operation: string;
    unidadeNome?: string;
    inputTokens: number;
    outputTokens: number;
    durationMs: number;
  }): void {
    if (!this.enabled) return;

    const { model, provider, operation, unidadeNome, inputTokens, outputTokens, durationMs } = params;
    const totalTokens = inputTokens + outputTokens;
    const costUsd = estimateCostUsd(model, inputTokens, outputTokens);

    const attrs: Record<string, string | number> = {
      'model.name': model,
      'model.provider': provider,
      'operation': operation,
    };
    if (unidadeNome) attrs['unidade.nome'] = unidadeNome;

    this.addCounter('app.ai.tokens.input', inputTokens, attrs, '{tokens}');
    this.addCounter('app.ai.tokens.output', outputTokens, attrs, '{tokens}');
    this.addCounter('app.ai.tokens.total', totalTokens, attrs, '{tokens}');
    this.addCounter('app.ai.request.cost', costUsd, { ...attrs, 'cost.currency': 'USD' }, 'USD');
    this.recordHistogram('app.ai.request.duration', durationMs, attrs, 'ms');
  }

  /**
   * Exporta todas as métricas coletadas via OTLP/HTTP.
   */
  async flush(): Promise<void> {
    if (!this.enabled) return;
    if (this.counters.size === 0 && this.histograms.size === 0) return;

    const metrics: (SumMetric | HistogramMetric)[] = [];

    for (const [name, { unit, dataPoints }] of this.counters) {
      metrics.push({
        name,
        unit,
        sum: { dataPoints, aggregationTemporality: 2, isMonotonic: true },
      });
    }

    for (const [name, { unit, dataPoints }] of this.histograms) {
      metrics.push({
        name,
        unit,
        histogram: { dataPoints, aggregationTemporality: 2 },
      });
    }

    const payload = {
      resourceMetrics: [{
        resource: {
          attributes: [
            { key: 'service.name', value: { stringValue: this.config.serviceName } },
            { key: 'service.version', value: { stringValue: this.config.serviceVersion } },
            { key: 'deployment.environment.name', value: { stringValue: this.config.environment } },
          ],
        },
        scopeMetrics: [{
          scope: { name: 'gidape-edge-function', version: '1.0.0' },
          metrics,
        }],
      }],
    };

    try {
      await fetch(`${this.config.endpoint}/v1/metrics`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });
    } catch (err) {
      console.warn('[Telemetry] Falha ao exportar métricas:', err instanceof Error ? err.message : err);
    }
  }
}

/**
 * Resultado de uma chamada LLM com dados de usage.
 */
export interface LlmCallResult {
  content: string;
  toolCalls?: any[];
  usage: {
    promptTokens: number;
    completionTokens: number;
    totalTokens: number;
  };
  model: string;
}

