## CHAIN OF VERIFICATION — ANTES DE EMITIR O JSON

1. Identifique todos os cabeçalhos de categoria no texto
2. Para cada item, confirme qual cabeçalho está ativo naquele trecho
3. Aplique o prefixo canônico correspondente
4. Se catálogo fornecido, busque o nome mais próximo
5. Conte total de itens e quantidades para preencher \`meta\`
6. Registre resumo no \`_debug_verification\``;

async function retryWithBackoff(fn, maxRetries = 3, baseDelay = 1000) {
  let lastError;
  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      return await fn();
    } catch (error) {
      lastError = error;
      if (attempt === maxRetries) throw lastError;
      const delay = baseDelay * Math.pow(2, attempt);
      console.log(`❌ Tentativa ${attempt + 1} falhou: ${lastError.message}. Tentando novamente em ${delay}ms...`);
      await new Promise((resolve) => setTimeout(resolve, delay));
    }
  }
  throw lastError;
}
async function makeOpenRouterRequestWithModel(prompt, model) {
  const apiKey = Deno.env.get('OPENROUTER_API_KEY');
  if (!apiKey) throw new Error('OPENROUTER_API_KEY not set');
  const fetchStart = Date.now();
  const response = await fetch('https://openrouter.ai/api/v1/chat/completions', {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${apiKey}`,
      'Content-Type': 'application/json',
      'HTTP-Referer': 'https://momma-stock-insight.vercel.app',
      'X-Title': 'momma-manual'
    },
    body: JSON.stringify({
      model: model,
      messages: [
        { role: 'system', content: SYSTEM_PROMPT },
        { role: 'user', content: prompt }
      ],
      temperature: 0.1,
      response_format: { type: 'json_object' }
    })
  });
  if (!response.ok) {
    const errorText = await response.text().catch(() => 'Erro desconhecido');
    console.error(`❌ OpenRouter API error with model ${model}: ${response.status} - ${errorText}`);
    logEvent('warning', 'fallback_api_error', { model, status: response.status, errorText });
    if (response.status === 502) throw new Error(`OpenRouter API temporariamente indisponível (502 Bad Gateway). Tentando novamente...`);
    else if (response.status === 503) throw new Error(`OpenRouter API sobrecarregada (503 Service Unavailable). Tentando novamente...`);
    else if (response.status === 429) throw new Error(`Rate limit atingido (429 Too Many Requests). Tentando novamente...`);
    else if (response.status >= 500) throw new Error(`Erro interno do servidor OpenRouter (${response.status}). Tentando novamente...`);
    else throw new Error(`OpenRouter API error: ${response.status} - ${errorText}`);
  }
  const data = await response.json();
  const durationMs = Date.now() - fetchStart;
  return { data, durationMs, model };
}
async function makeOpenRouterRequest(prompt) {
  let lastError;
  for (const model of FALLBACK_MODELS) {
    try {
      const res = await retryWithBackoff(async () => {
        return await makeOpenRouterRequestWithModel(prompt, model);
      }, 3, 2000);
      return res;
    } catch (err) {
      lastError = err;
      logEvent('warning', 'fallback_model_fail', { model, error: err instanceof Error ? err.message : String(err) });
      continue;
    }
  }
  throw lastError || new Error('Todos os modelos de fallback falharam');
}
