    }
    logEvent('info', 'input_received', { contentLength: String(prompt || '').length, hasCatalog: Array.isArray(productCatalog) && productCatalog.length > 0 });
    if (streamRequested) {
      rootSpan.setAttribute('request.mode', 'stream');
      rootSpan.end();
      Promise.all([tracer.flush(), metrics.flush()]).catch(() => {});
      return await streamOpenRouterReasoning(prompt, FALLBACK_MODELS, tracer, metrics);
    }
    rootSpan.setAttribute('request.mode', 'non-stream');
    const llmSpan = tracer.startSpan('llm-call-openrouter', rootSpan.spanId);
    const result = await makeOpenRouterRequest(prompt);
    const data = result.data;
    const llmDurationMs = result.durationMs;
    const actualModel = data?.model || result.model;
    llmSpan.setAttribute('llm.model', actualModel);
    llmSpan.setAttribute('llm.provider', 'openrouter');
    const usage = data?.usage;
    if (usage) {
      const inputTokens = usage.prompt_tokens ?? 0;
      const outputTokens = usage.completion_tokens ?? 0;
      llmSpan.setAttribute('llm.usage.input_tokens', inputTokens);
      llmSpan.setAttribute('llm.usage.output_tokens', outputTokens);
      llmSpan.setAttribute('llm.usage.total_tokens', usage.total_tokens ?? (inputTokens + outputTokens));
      metrics.recordLlmCall({
        model: actualModel,
        provider: 'openrouter',
        operation: 'requisition-parse',
        inputTokens,
        outputTokens,
        durationMs: llmDurationMs,
      });
    }
    llmSpan.end();
    const aiResponse = data.choices[0].message.content;
    logEvent('info', 'openrouter_response', { model: actualModel, contentLength: aiResponse.length, content: aiResponse });
    let parsedResponse;
    try {
      let cleanResponse = aiResponse.trim();
      if (cleanResponse.startsWith('```json')) {
        cleanResponse = cleanResponse.replace(/^```json\s*/, '').replace(/\s*```$/, '');
      }
      parsedResponse = JSON.parse(cleanResponse);
    } catch (e) {
      logEvent('error', 'parse_error', { model: null, content: aiResponse });
      throw new Error('Erro ao processar resposta da IA');
    }
    try {
      const categories = Array.isArray(parsedResponse?.categories) ? parsedResponse.categories : [];
      if (categories.length > 0) {
        const flattened = categories.flatMap((cat) => Array.isArray(cat?.items) ? cat.items.map((it) => ({
          name: repairItemName(String(it?.name || '').trim(), String(cat?.category || '')),
          source_text: it?.source_text ? String(it.source_text) : undefined,
          requested: Number(it?.requested ?? 1),
          sent: it?.sent ?? null,
          observation: undefined,
          category: String(cat?.category || '').trim()
        })) : []);
        parsedResponse.items = flattened;
        const totalItems = flattened.length;
        const totalRequested = flattened.reduce((sum, it) => sum + (Number(it.requested) || 0), 0);
        parsedResponse.meta = parsedResponse.meta || { total_items: totalItems, total_requested: totalRequested };
      } else if (!Array.isArray(parsedResponse?.items)) {
        parsedResponse.items = [];
        parsedResponse.categories = [];
        parsedResponse.meta = parsedResponse.meta || { total_items: 0, total_requested: 0 };
      }
    } catch (flattenError) {
      console.warn('Falha ao normalizar categorias/items:', flattenError);
    }
    logEvent('info', 'result_return', { items: parsedResponse?.items?.length ?? 0, categories: parsedResponse?.categories?.length ?? 0, meta: parsedResponse?.meta });
    rootSpan.end();
    Promise.all([tracer.flush(), metrics.flush()]).catch(() => {});
    return new Response(JSON.stringify(parsedResponse), {
      headers: {
        ...corsHeaders,
        'Content-Type': 'application/json',
        'traceparent': tracer.getResponseTraceparent(),
      }
    });
  } catch (error) {
    console.error('❌ Error in process-requisition-ai:', error);
    logEvent('error', 'fatal', { error: error instanceof Error ? error.message : String(error) });
    rootSpan.endWithError(error instanceof Error ? error.message : String(error));
    Promise.all([tracer.flush(), metrics.flush()]).catch(() => {});
    let statusCode = 500;
    let errorMessage = 'Erro interno do servidor';
    if (error instanceof Error) {
      if (error.message.includes('OpenRouter API error: 4')) {
        statusCode = 400;
        errorMessage = 'Erro na requisição para a API de IA';
      } else if (error.message.includes('OpenRouter') || error.message.includes('502') || error.message.includes('503')) {
        statusCode = 502;
        errorMessage = 'Serviço de IA temporariamente indisponível. Tente novamente em alguns minutos.';
      } else if (error.message.includes('Erro ao processar resposta da IA')) {
        statusCode = 422;
        errorMessage = 'Erro ao processar resposta da IA';
      } else {
        errorMessage = error.message;
      }
    }
    return new Response(JSON.stringify({
      error: errorMessage,
      details: error instanceof Error ? error.message : error.toString(),
      timestamp: new Date().toISOString()
    }), {
      status: statusCode,
      headers: {
        ...corsHeaders,
        'Content-Type': 'application/json',
        'traceparent': tracer.getResponseTraceparent(),
      }
    });
  }
});
function appendOverlapDedup(buffer, chunk) {
  if (!buffer) return chunk;
  const max = Math.min(buffer.length, 256);
  for (let k = max; k > 0; k--) {
    if (buffer.slice(-k) === chunk.slice(0, k)) {
      return buffer + chunk.slice(k);
    }
  }
  return buffer + chunk;
}
function normalizeReasoningText(input) {
  let text = input.replace(/\r\n/g, "\n");
  text = text.replace(/\*+/g, "");
  text = text.replace(/[^\S\n]+/g, " ");
  text = text.replace(/\n{3,}/g, "\n\n");
  text = text.replace(/\s*:\s*/g, ": ");
  text = text.replace(/\s*,\s*/g, ", ");
  text = text.replace(/\s*\.\s*/g, ". ");
  text = text.replace(/ {2,}/g, " ").trim();
  try {
    const wordDedup = new RegExp("(\\b[\\p{L}0-9]+\\b)(?:\\s+\\1)+", "gu");
    text = text.replace(wordDedup, "$1");
    const phraseDedup = new RegExp("((?:\\b[\\p{L}0-9]+\\b\\s?){2,6})(?:\\s+\\1)+", "gu");
    text = text.replace(phraseDedup, "$1");
  } catch (e) { console.debug('[normalize] skip'); }
  return text;
}

/**
 * Telemetria OpenTelemetry leve para Supabase Edge Functions (Deno).
 */

export interface EdgeTelemetryConfig {
  enabled: boolean;
  endpoint: string;
  serviceName: string;
  serviceVersion: string;
  environment: string;
}

export function getEdgeTelemetryConfig(): EdgeTelemetryConfig {
  return {
    enabled: Deno.env.get('OTEL_ENABLED') === 'true',
    endpoint: Deno.env.get('OTEL_ENDPOINT') || 'http://localhost:4318',
    serviceName: Deno.env.get('OTEL_SERVICE_NAME') || 'gidape-edge-requisicao-ia',
    serviceVersion: Deno.env.get('OTEL_SERVICE_VERSION') || '0.0.0',
    environment: Deno.env.get('OTEL_ENVIRONMENT') || 'dev',
  };
}

export interface TraceParent {
  version: string;
  traceId: string;
  parentSpanId: string;
  traceFlags: number;
}

export function parseTraceparent(header: string | null): TraceParent | null {
  if (!header) return null;
  const parts = header.trim().split('-');
  if (parts.length !== 4) return null;
  const [version, traceId, parentSpanId, flagsHex] = parts;
  if (version.length !== 2 || traceId.length !== 32 || parentSpanId.length !== 16 || flagsHex.length !== 2) return null;
  if (/^0+$/.test(traceId)) return null;
  return { version, traceId, parentSpanId, traceFlags: parseInt(flagsHex, 16) };
}

export function generateHexId(bytes: number): string {
  const array = new Uint8Array(bytes);
  crypto.getRandomValues(array);
  return Array.from(array, (b) => b.toString(16).padStart(2, '0')).join('');
}

export function generateTraceId(): string { return generateHexId(16); }
export function generateSpanId(): string { return generateHexId(8); }
export function formatTraceparent(traceId: string, spanId: string, sampled: boolean = true): string {
  return `00-${traceId}-${spanId}-${sampled ? '01' : '00'}`;
}

export interface SpanData {
  traceId: string;
  spanId: string;
  parentSpanId: string;
  name: string;
  kind: number;
  startTimeUnixNano: bigint;
  endTimeUnixNano: bigint;
  attributes: Array<{ key: string; value: { stringValue?: string; intValue?: number; doubleValue?: number; boolValue?: boolean } }>;
  status: { code: number; message?: string };
  events: Array<{ name: string; timeUnixNano: bigint; attributes: SpanData['attributes'] }>;
}

export interface EdgeSpan {
  setAttribute(key: string, value: string | number | boolean): void;
  addEvent(name: string, attributes?: Record<string, string | number | boolean>): void;
  end(): void;
  endWithError(message: string): void;
  readonly spanId: string;
}

export class EdgeTracer {
  private readonly config: EdgeTelemetryConfig;
  private readonly traceId: string;
  private readonly rootSpanId: string;
  private readonly spans: SpanData[] = [];
  private readonly enabled: boolean;

  constructor(req: Request, configOverride?: Partial<EdgeTelemetryConfig>) {
    this.config = { ...getEdgeTelemetryConfig(), ...configOverride };
    this.enabled = this.config.enabled;
    const traceparent = parseTraceparent(req.headers.get('traceparent'));
    if (traceparent) {
      this.traceId = traceparent.traceId;
      this.rootSpanId = traceparent.parentSpanId;
    } else {
      this.traceId = generateTraceId();
      this.rootSpanId = generateSpanId();
    }
  }

  getTraceId(): string { return this.traceId; }
  getResponseTraceparent(): string { return formatTraceparent(this.traceId, this.rootSpanId); }

  startSpan(name: string, parentSpanId?: string): EdgeSpan {
    if (!this.enabled) return this.createNoopSpan();
    const spanId = generateSpanId();
    const startTime = BigInt(Date.now()) * 1_000_000n;
    const attributes: SpanData['attributes'] = [];
    const events: SpanData['events'] = [];
    let ended = false;
    const span: EdgeSpan = {
      spanId,
      setAttribute: (key: string, value: string | number | boolean) => {
        if (ended) return;
        const attr: SpanData['attributes'][0] = { key, value: {} };
        if (typeof value === 'string') attr.value.stringValue = value;
        else if (typeof value === 'boolean') attr.value.boolValue = value;
        else if (Number.isInteger(value)) attr.value.intValue = value as number;
        else attr.value.doubleValue = value as number;
        attributes.push(attr);
      },
      addEvent: (eventName: string, eventAttrs?: Record<string, string | number | boolean>) => {
        if (ended) return;
        const otelAttrs: SpanData['attributes'] = [];
        if (eventAttrs) {
          for (const [k, v] of Object.entries(eventAttrs)) {
            const attr: SpanData['attributes'][0] = { key: k, value: {} };
            if (typeof v === 'string') attr.value.stringValue = v;
            else if (typeof v === 'boolean') attr.value.boolValue = v;
            else if (Number.isInteger(v)) attr.value.intValue = v as number;
            else attr.value.doubleValue = v as number;
            otelAttrs.push(attr);
          }
        }
        events.push({ name: eventName, timeUnixNano: BigInt(Date.now()) * 1_000_000n, attributes: otelAttrs });
      },
      end: () => {
        if (ended) return;
        ended = true;
        const endTime = BigInt(Date.now()) * 1_000_000n;
        this.spans.push({ traceId: this.traceId, spanId, parentSpanId: parentSpanId || this.rootSpanId, name, kind: parentSpanId ? 0 : 1, startTimeUnixNano: startTime, endTimeUnixNano: endTime, attributes, status: { code: 1 }, events });
      },
      endWithError: (message: string) => {
        if (ended) return;
        ended = true;
        const endTime = BigInt(Date.now()) * 1_000_000n;
        this.spans.push({ traceId: this.traceId, spanId, parentSpanId: parentSpanId || this.rootSpanId, name, kind: parentSpanId ? 0 : 1, startTimeUnixNano: startTime, endTimeUnixNano: endTime, attributes, status: { code: 2, message }, events });
      },
    };
    return span;
  }

  async flush(): Promise<void> {
    if (!this.enabled || this.spans.length === 0) return;
    const payload = {
      resourceSpans: [{
        resource: { attributes: [
          { key: 'service.name', value: { stringValue: this.config.serviceName } },
          { key: 'service.version', value: { stringValue: this.config.serviceVersion } },
          { key: 'deployment.environment.name', value: { stringValue: this.config.environment } },
        ]},
        scopeSpans: [{ scope: { name: 'gidape-edge-function', version: '1.0.0' }, spans: this.spans.map(s => ({
          traceId: s.traceId, spanId: s.spanId, parentSpanId: s.parentSpanId, name: s.name, kind: s.kind,
          startTimeUnixNano: s.startTimeUnixNano.toString(), endTimeUnixNano: s.endTimeUnixNano.toString(),
          attributes: s.attributes, status: s.status,
          events: s.events.map(e => ({ ...e, timeUnixNano: e.timeUnixNano.toString() })),
        })) }],
      }],
    };
    try {
      await fetch(`${this.config.endpoint}/v1/traces`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
    } catch (err) {
      console.warn('[Telemetry] Falha ao exportar spans:', err instanceof Error ? err.message : err);
    }
  }

  private createNoopSpan(): EdgeSpan {
    return { spanId: '0'.repeat(16), setAttribute: () => {}, addEvent: () => {}, end: () => {}, endWithError: () => {} };
  }
}

interface MetricDataPoint {
  attributes: Array<{ key: string; value: { stringValue?: string; intValue?: number; doubleValue?: number } }>;
  startTimeUnixNano: string;
  timeUnixNano: string;
  asInt?: string;
  asDouble?: number;
}

interface SumMetric {
  name: string;
  unit: string;
  sum: { dataPoints: MetricDataPoint[]; aggregationTemporality: number; isMonotonic: boolean; };
}

interface HistogramDataPoint {
  attributes: MetricDataPoint['attributes'];
  startTimeUnixNano: string;
  timeUnixNano: string;
  count: string;
  sum: number;
  min: number;
  max: number;
  bucketCounts: string[];
  explicitBounds: number[];
}

interface HistogramMetric {
  name: string;
  unit: string;
  histogram: { dataPoints: HistogramDataPoint[]; aggregationTemporality: number; };
}

function toOtelAttributes(attrs: Record<string, string | number>): MetricDataPoint['attributes'] {
  return Object.entries(attrs).map(([key, value]) => ({
    key,
    value: typeof value === 'string' ? { stringValue: value } : Number.isInteger(value) ? { intValue: value } : { doubleValue: value },
  }));
}

const MODEL_COST_PER_1M: Record<string, { input: number; output: number }> = {
  'deepseek/deepseek-r1-0528:free': { input: 0, output: 0 },
  'openai/gpt-oss-120b:free': { input: 0, output: 0 },
  'x-ai/grok-4.1-fast:free': { input: 0, output: 0 },
  'x-ai/grok-4.1-fast': { input: 3, output: 15 },
  'x-ai/grok-4-fast': { input: 3, output: 15 },
  'deepseek/deepseek-r1-distill-llama-70b:free': { input: 0, output: 0 },
  'google/gemini-2.0-flash-001': { input: 0.1, output: 0.4 },
};

function estimateCostUsd(model: string, inputTokens: number, outputTokens: number): number {
  const pricing = MODEL_COST_PER_1M[model];
  if (!pricing) return 0;
  return (inputTokens / 1_000_000) * pricing.input + (outputTokens / 1_000_000) * pricing.output;
}

export class EdgeMetrics {
  private readonly config: EdgeTelemetryConfig;
  private readonly enabled: boolean;
  private readonly startTimeNano: string;
  private readonly counters: Map<string, { unit: string; dataPoints: MetricDataPoint[] }> = new Map();
  private readonly histograms: Map<string, { unit: string; bounds: number[]; dataPoints: HistogramDataPoint[] }> = new Map();

  constructor(configOverride?: Partial<EdgeTelemetryConfig>) {
    this.config = { ...getEdgeTelemetryConfig(), ...configOverride };
    this.enabled = this.config.enabled;
    this.startTimeNano = (BigInt(Date.now()) * 1_000_000n).toString();
  }

  addCounter(name: string, value: number, attributes: Record<string, string | number>, unit = '1'): void {
    if (!this.enabled) return;
    if (!this.counters.has(name)) this.counters.set(name, { unit, dataPoints: [] });
    this.counters.get(name)!.dataPoints.push({
      attributes: toOtelAttributes(attributes),
      startTimeUnixNano: this.startTimeNano,
      timeUnixNano: (BigInt(Date.now()) * 1_000_000n).toString(),
      asInt: String(Math.round(value)),
    });
  }

  recordHistogram(name: string, value: number, attributes: Record<string, string | number>, unit = 'ms', bounds = [50, 100, 250, 500, 1000, 2500, 5000, 10000, 30000, 60000]): void {
    if (!this.enabled) return;
    if (!this.histograms.has(name)) this.histograms.set(name, { unit, bounds, dataPoints: [] });
    const bucketCounts = new Array(bounds.length + 1).fill(0);
    for (let i = 0; i < bounds.length; i++) {
      if (value <= bounds[i]) { bucketCounts[i]++; break; }
      if (i === bounds.length - 1) bucketCounts[bounds.length]++;
    }
    this.histograms.get(name)!.dataPoints.push({
      attributes: toOtelAttributes(attributes),
      startTimeUnixNano: this.startTimeNano,
      timeUnixNano: (BigInt(Date.now()) * 1_000_000n).toString(),
      count: '1', sum: value, min: value, max: value,
      bucketCounts: bucketCounts.map(String), explicitBounds: bounds,
    });
  }

  recordLlmCall(params: { model: string; provider: string; operation: string; unidadeNome?: string; inputTokens: number; outputTokens: number; durationMs: number; }): void {
    if (!this.enabled) return;
    const { model, provider, operation, unidadeNome, inputTokens, outputTokens, durationMs } = params;
    const totalTokens = inputTokens + outputTokens;
    const costUsd = estimateCostUsd(model, inputTokens, outputTokens);
    const attrs: Record<string, string | number> = { 'model.name': model, 'model.provider': provider, 'operation': operation };
    if (unidadeNome) attrs['unidade.nome'] = unidadeNome;
    this.addCounter('app.ai.tokens.input', inputTokens, attrs, '{tokens}');
    this.addCounter('app.ai.tokens.output', outputTokens, attrs, '{tokens}');
    this.addCounter('app.ai.tokens.total', totalTokens, attrs, '{tokens}');
    this.addCounter('app.ai.request.cost', costUsd, { ...attrs, 'cost.currency': 'USD' }, 'USD');
    this.recordHistogram('app.ai.request.duration', durationMs, attrs, 'ms');
  }

  async flush(): Promise<void> {
    if (!this.enabled) return;
    if (this.counters.size === 0 && this.histograms.size === 0) return;
    const metrics: (SumMetric | HistogramMetric)[] = [];
    for (const [name, { unit, dataPoints }] of this.counters) {
      metrics.push({ name, unit, sum: { dataPoints, aggregationTemporality: 2, isMonotonic: true } });
    }
    for (const [name, { unit, dataPoints }] of this.histograms) {
      metrics.push({ name, unit, histogram: { dataPoints, aggregationTemporality: 2 } });
    }
    const payload = {
      resourceMetrics: [{
        resource: { attributes: [
          { key: 'service.name', value: { stringValue: this.config.serviceName } },
          { key: 'service.version', value: { stringValue: this.config.serviceVersion } },
          { key: 'deployment.environment.name', value: { stringValue: this.config.environment } },
        ]},
        scopeMetrics: [{ scope: { name: 'gidape-edge-function', version: '1.0.0' }, metrics }],
      }],
    };
    try {
      await fetch(`${this.config.endpoint}/v1/metrics`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
    } catch (err) {
      console.warn('[Telemetry] Falha ao exportar métricas:', err instanceof Error ? err.message : err);
    }
  }
}

export interface LlmCallResult {
  content: string;
  toolCalls?: any[];
  usage: { promptTokens: number; completionTokens: number; totalTokens: number; };
  model: string;
}
